H.background();
const W = H.W;
const F = P.F, m = Math.max(0.1, P.m);
const a = F / m;
const groundY = 360;
H.line(40, groundY, W - 40, groundY, { color: H.colors.grid, width: 2 });
const cx = W / 2;
const span = 220;
const xpos = cx + span * Math.sin(t * 0.9) * H.clamp(a / 12, 0.05, 1);
const bw = 90, bh = 64;
const bx = xpos - bw / 2, by = groundY - bh;
H.rect(bx, by, bw, bh, { fill: H.colors.panel, stroke: H.colors.accent, width: 2, radius: 6 });
H.text(m.toFixed(1) + " kg", xpos, by + bh / 2, { color: H.colors.ink, size: 14, align: "center", baseline: "middle" });
const dir = Math.cos(t * 0.9) >= 0 ? 1 : -1;
const alen = H.clamp(Math.abs(F) * 6, 12, 180) * Math.sign(F || 1) * dir;
H.arrow(xpos, by + bh / 2, xpos + alen, by + bh / 2, { color: H.colors.accent2, width: 4 });
H.text("F", xpos + alen + 8 * Math.sign(alen || 1), by + bh / 2 - 12, { color: H.colors.accent2, size: 14, align: "center" });
const aarr = H.clamp(a * 12, 8, 200) * dir;
H.arrow(xpos, by - 18, xpos + aarr, by - 18, { color: H.colors.good, width: 3 });
H.text("a", xpos + aarr + 8 * Math.sign(aarr || 1), by - 30, { color: H.colors.good, size: 13, align: "center" });
H.text("Newton's 2nd law:  F = m a", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Same force on a heavier block gives a smaller acceleration.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("F = " + F.toFixed(1) + " N", 24, 84, { color: H.colors.accent2, size: 14 });
H.text("m = " + m.toFixed(1) + " kg", 24, 104, { color: H.colors.sub, size: 14 });
H.text("a = F/m = " + a.toFixed(2) + " m/s^2", 24, 124, { color: H.colors.good, size: 14 });
